+            i++;
+          } else if (c === "\n") {
+            endRow();
+            i++;
+          } else if (i + 1 < text.length) {
+            if (text[i + 1] === "\n") {
+              endRow();
+              i += 2;
+            } else {
+              this.#field += "\r";
+              i++;
+            }
+          } else if (final) {
+            this.#field += "\r";
+            i++;
+          } else {
+            this.#carry = "\r";
+            i++;
+          }
+          break;
+        }
+        case "quoted": {
+          const j = text.indexOf('"', i);
+          if (j === -1) {
+            this.#field += text.slice(i);
+            i = text.length;
+            break;
+          }
+          this.#field += text.slice(i, j);
+          if (j + 1 < text.length && text[j + 1] === '"') {
+            this.#field += '"';
+            i = j + 2;
+          } else if (j + 1 === text.length && !final) {
+            this.#carry = '"';
+            i = j + 1;
+          } else {
+            this.#state = "closed";
+            i = j + 1;
+          }
+          break;
+        }
+        case "closed": {
+          const c = text[i];
+          if (c === ",") {
+            endField();
+            i++;
+          } else if (c === "\n") {
+            endRow();
+            i++;
+          } else if (c === "\r" && text[i + 1] === "\n") {
+            endRow();
+            i += 2;
+          } else if (c === "\r" && i + 1 === text.length && !final) {
+            this.#carry = "\r";
+            i++;
