+const flush = async () => {
+  for (let i = 0; i < 10; i++) await Promise.resolve();
+};
+
+function rng(seed: number) {
+  return () => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let t = seed;
+    t = Math.imul(t ^ (t >>> 15), t | 1);
+    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+test("a bad limit or retries count is refused before any task runs", async () => {
+  for (const limit of [0, -1, 1.5, NaN, "2" as any]) {
+    let calls = 0;
+    await expect(runPool([() => ++calls], limit)).rejects.toBeInstanceOf(RangeError);
+    expect(calls).toBe(0);
+  }
+  for (const retries of [-1, 1.5, NaN]) {
+    let calls = 0;
+    await expect(runPool([() => ++calls], 1, { retries })).rejects.toBeInstanceOf(RangeError);
+    expect(calls).toBe(0);
+  }
+});
+
+test("a limit of Infinity and retries of 0 are accepted", async () => {
+  const out = await runPool([() => 1, () => 2], Infinity, { retries: 0 });
+  expect(out.map((r) => r.status)).toEqual(["fulfilled", "fulfilled"]);
+});
