+  const gates = Array.from({ length: 10 }, () => gate<number>());
+  const live = new Set<number>();
+  const started: number[] = [];
+  let peak = 0;
+  const tasks = gates.map((g, i) => () => {
+    started.push(i);
+    live.add(i);
+    peak = Math.max(peak, live.size);
+    return g.p.finally(() => live.delete(i));
+  });
